const describeError = (error) => [
	error.codigo_error ? `${error.codigo_error}` : null,
	error.descripcion_error || "sin descripción",
	error.seccion_error ? `(${error.seccion_error})` : null
].filter(Boolean).join(" ");
const buildMonitoringFormPatch = (context) => {
	const state = context.currentState;
	const activeErrors = Array.isArray(state?.errores_activos) ? state.errores_activos : [];
	const model = inferEquipmentModel(context.equipment?.model) || inferEquipmentModelFromSerial(context.serial);
	const recent = context.recentErrors.slice(0, 12);
	const lines = [
		context.equipment ? `Equipo ${context.equipment.model || "modelo no registrado"} · ${context.equipment.clientName || "cliente no registrado"}${context.equipment.location ? ` · ${context.equipment.location}` : ""}` : "Equipo sin registro maestro en Monitoreo.",
		state ? `Estado actual: ${state.estado_actual || "desconocido"}${state.descripcion_estado ? ` · ${state.descripcion_estado}` : ""}${state.last_event_at ? ` · ${formatDateTime(state.last_event_at)}` : ""}` : "Sin estado vigente publicado por el monitor.",
		activeErrors.length ? `Alarmas activas (${activeErrors.length}): ${activeErrors.slice(0, 6).map(describeError).join("; ")}` : null,
		recent.length ? `Últimos eventos: ${recent.map((error) => `${describeError(error)} · ${formatDateTime(error.detected_at || error.created_at)}`).join("; ")}` : null
	].filter((line) => Boolean(line));
	const opticalReject = [...activeErrors, ...recent].some((error) => /rechazo.*(opt|ópt|absorb)|optical reject|reject.*optic/i.test(`${error.descripcion_error || ""} ${error.seccion_error || ""}`));
	const evidenceItem = {
		id: `monitoring-${context.serial}`,
		type: "report",
		title: `Monitoreo · ${context.serial}`,
		value: state?.estado_actual ? `Estado ${state.estado_actual} · ${activeErrors.length} alarmas activas` : `${recent.length} eventos recientes`,
		note: "",
		capturedAt: context.loadedAt,
		ocrSummary: lines.slice(0, 6),
		sourceStatus: "validated",
		sourceReference: `monitoreo · ${context.serial}`,
		derivedData: {
			signalPatch: opticalReject ? { opticalRejectObserved: true } : {},
			serviceTests: [],
			observationLines: lines,
			observedInterferents: []
		}
	};
	const notes = [
		context.equipment ? `Identidad: ${context.equipment.model || "modelo no registrado"} de ${context.equipment.clientName || "cliente no registrado"}.` : "La serie no está en el maestro de equipos.",
		state ? `${activeErrors.length} alarmas activas · estado ${state.estado_actual || "desconocido"}.` : "Sin estado vigente del monitor.",
		...context.warnings
	];
	return {
		patch: {
			sourceKind: "monitoring",
			sourceId: context.serial,
			label: `Monitoreo ${context.serial}`,
			fields: {
				equipmentModel: model || void 0,
				serialNumber: context.serial
			},
			fieldMode: "fill",
			forceFields: ["serialNumber", ...model ? ["equipmentModel"] : []],
			signals: opticalReject ? { opticalRejectObserved: true } : void 0,
			observationBlock: {
				tag: "MON",
				text: lines.join("\n")
			},
			evidenceItems: [evidenceItem]
		},
		notes
	};
};

